/**
 * ActionStepsCard.tsx
 * Displays unfinished action steps from user's playbooks
 */

import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  ActivityIndicator,
  FlatList,
} from 'react-native';
import Ionicons from 'react-native-vector-icons/Ionicons';
import { Colors } from '../../theme/colors';
import { useAuth } from '../../context/IndustryStandardAuthContext';
import { supabase } from '../../services/supabaseClient';

interface ActionStep {
  id: string;
  title: string;
  description?: string;
  playbookTitle: string;
  playbookId: string;
  stepIndex: number;
  isCompleted: boolean;
  dueDate?: string;
  priority?: 'high' | 'medium' | 'low';
}

interface ActionStepsCardProps {
  onStepPress?: (step: ActionStep) => void;
  onViewAll?: () => void;
}



const ActionStepsCard: React.FC<ActionStepsCardProps> = ({ onStepPress, onViewAll }) => {
  const { user } = useAuth();
  const [actionSteps, setActionSteps] = useState<ActionStep[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchActionSteps = async () => {
    if (!user) {return;}

    try {
      setLoading(true);
      setError(null);

      // Fetch user's playbooks
      const { data, error } = await supabase
        .from('playbook_action_steps')
        .select(`
          *,
          playbook:playbooks(*)
        `)
        .eq('completed', false)
        .limit(10);

      if (error) {
        console.error('Error fetching action steps:', error);
        throw error;
      }

      if (!data || data.length === 0) {
        setActionSteps([]);
        return;
      }

      const _progressData = await supabase
        .from('user_progress')
        .select('*');

      setActionSteps(actionSteps);

    } catch (err) {
      console.error('Error fetching action steps:', err);
      setError('Unable to load action steps');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchActionSteps();
  }, [user]);

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'high': return Colors.alertCoral;
      case 'medium': return Colors.faithGold;
      case 'low': return Colors.successGreen;
      default: return Colors.faithGold;
    }
  };

  const getPriorityIcon = (priority: string) => {
    switch (priority) {
      case 'high': return 'alert-circle';
      case 'medium': return 'time';
      case 'low': return 'checkmark-circle-outline';
      default: return 'time';
    }
  };

  const renderActionStep = ({ item }: { item: ActionStep }) => (
    <TouchableOpacity
      style={styles.stepItem}
      onPress={() => onStepPress?.(item)}
      activeOpacity={0.8}
    >
      <View style={styles.stepHeader}>
        <Ionicons
          name={getPriorityIcon(item.priority || 'medium')}
          size={16}
          color={getPriorityColor(item.priority || 'medium')}
        />
        <Text style={styles.stepTitle} numberOfLines={1}>
          {item.title}
        </Text>
      </View>

      <Text style={styles.playbookName} numberOfLines={1}>
        From: {item.playbookTitle}
      </Text>

      {item.description && (
        <Text style={styles.stepDescription} numberOfLines={2}>
          {item.description}
        </Text>
      )}
    </TouchableOpacity>
  );

  const renderEmptyState = () => (
    <View style={styles.emptyContainer}>
      <Ionicons name="checkmark-circle" size={32} color={Colors.successGreen} />
      <Text style={styles.emptyTitle}>All Caught Up!</Text>
      <Text style={styles.emptyDescription}>
        You've completed all your action steps. Great work!
      </Text>
    </View>
  );

  if (loading) {
    return (
      <View style={styles.card}>
        <View style={styles.header}>
          <Ionicons name="checkmark-circle" size={24} color={Colors.alertCoral} />
          <Text style={styles.title}>Unfinished Steps</Text>
        </View>
        <View style={styles.loadingContainer}>
          <ActivityIndicator size="small" color={Colors.alertCoral} />
          <Text style={styles.loadingText}>Loading steps...</Text>
        </View>
      </View>
    );
  }

  return (
    <View style={styles.card}>
      <View style={styles.header}>
        <Ionicons name="checkmark-circle" size={24} color={Colors.alertCoral} />
        <Text style={styles.title}>Unfinished Steps</Text>
        {actionSteps.length > 0 && (
          <TouchableOpacity onPress={onViewAll} style={styles.viewAllButton}>
            <Text style={styles.viewAllText}>View All</Text>
            <Ionicons name="chevron-forward" size={16} color={Colors.alertCoral} />
          </TouchableOpacity>
        )}
      </View>

      {error ? (
        <View style={styles.errorContainer}>
          <Text style={styles.errorText}>{error}</Text>
          <TouchableOpacity onPress={fetchActionSteps} style={styles.retryButton}>
            <Text style={styles.retryText}>Try Again</Text>
          </TouchableOpacity>
        </View>
      ) : actionSteps.length === 0 ? (
        renderEmptyState()
      ) : (
        <FlatList
          data={actionSteps}
          renderItem={renderActionStep}
          keyExtractor={(item) => item.id}
          showsVerticalScrollIndicator={false}
          scrollEnabled={false}
        />
      )}
    </View>
  );
};

